pub fn router(state: Arc<AppState>) -> Router {
    Router::new()
        .route("/health", get(health))
        .route("/admin/metrics", get(admin_metrics))
        .route("/admin/final-scope-shadow", get(admin_final_scope_shadow))
        .route("/admin/cache-validation", get(admin_cache_validation))
        .route("/admin/cache-affinity", get(admin_cache_affinity))
        .route("/admin/cache-capabilities", get(admin_cache_capabilities))
        .route(
            "/admin/release-champion/status",
            get(admin_release_champion_status),
        )
        .route(
            "/admin/release-champion/run",
            post(admin_release_champion_run),
        )
        .route(
            "/admin/cache-capabilities/probe",
            post(admin_probe_cache_capabilities),
        )
        .route(
            "/admin/isolated-response-continuation/probe",
            post(admin_probe_isolated_response_continuation),
        )
        .route("/v1/models", get(list_models))
        .route("/v1/chat/completions", post(chat_completions))
        .route("/v1/responses", post(responses))
        .route("/v1/responses/compact", post(responses_compact_legacy))
        .route("/codex/v1/models", get(codex_list_models))
        .route("/codex/v1/chat/completions", post(codex_chat_completions))
        .route("/codex/v1/responses", post(codex_responses))
        .route(
            "/codex/v1/responses/compact",
            post(codex_responses_compact_legacy),
        )
        .route(
            "/v1/responses/:response_id/compact",
            post(responses_compact),
        )
        .route(
            "/codex/v1/responses/:response_id/compact",
            post(codex_responses_compact),
        )
        .route("/v1/messages", post(messages))
        .layer(DefaultBodyLimit::max(200 * 1024 * 1024))
        .layer(middleware::from_fn_with_state(
            state.clone(),
            preauthorize_generation_request,
        ))
        .with_state(state)
}

/// Reject invalid remote generation requests before Axum's `Bytes` extractor
/// buffers a potentially large full-replay body. The handlers repeat the
/// authorization check after extraction so this guard is only a resource
/// boundary, not a second authorization policy.
async fn preauthorize_generation_request(
    AxumState(state): AxumState<Arc<AppState>>,
    request: Request,
    next: Next,
) -> Response {
    let path = request.uri().path();
    if request.method() != Method::POST
        || !(path.starts_with("/v1/") || path.starts_with("/codex/v1/"))
    {
        return next.run(request).await;
    }
    let forced_agent_id = path.starts_with("/codex/").then_some("codex");
    if let Err(response) = authorize_for_agent(&state, request.headers(), forced_agent_id).await {
        let body = request.into_body();
        tokio::spawn(async move {
            let _ = tokio::time::timeout(TokioDuration::from_secs(2), async move {
                let mut stream = body.into_data_stream();
                while stream.next().await.is_some() {}
            })
            .await;
        });
        return response;
    }
    next.run(request).await
}

