    #[test]
    fn stream_proxy_requires_client_stream_and_actual_sse_response() {
        let body = json!({ "stream": true });
        assert!(should_proxy_upstream_as_stream(
            true,
            true,
            false,
            false,
            &body,
            "text/event-stream"
        ));
        assert!(!should_proxy_upstream_as_stream(
            true,
            false,
            false,
            false,
            &body,
            "text/event-stream"
        ));
        assert!(!should_proxy_upstream_as_stream(
            true,
            true,
            true,
            false,
            &body,
            "text/event-stream"
        ));
        assert!(!should_proxy_upstream_as_stream(
            true,
            true,
            false,
            true,
            &body,
            "application/json"
        ));
        assert!(!should_proxy_upstream_as_stream(
            true,
            true,
            false,
            false,
            &body,
            "application/json"
        ));
        assert!(should_proxy_upstream_as_stream(
            true,
            true,
            false,
            true,
            &body,
            "text/event-stream"
        ));
        assert!(supports_incremental_cross_protocol_stream(
            &Channel::Responses,
            &Channel::Chat
        ));
        assert!(supports_incremental_cross_protocol_stream(
            &Channel::Responses,
            &Channel::Anthropic
        ));
        assert!(supports_incremental_cross_protocol_stream(
            &Channel::Chat,
            &Channel::Responses
        ));
        assert!(supports_incremental_cross_protocol_stream(
            &Channel::Anthropic,
            &Channel::Responses
        ));

        let mut provider = test_responses_provider("http://127.0.0.1/v1".to_string());
        provider.channel = Channel::Chat;
        provider.models = vec![ModelConfig {
            id: "non-streaming-model".to_string(),
            request_model_id: None,
            display_name: "non-streaming-model".to_string(),
            context_window: None,
            output_window: None,
            reasoning_effort_override_enabled: false,
            reasoning_effort: None,
            supported_reasoning_efforts: Vec::new(),
            supports_tools: true,
            supports_streaming: false,
            enabled: true,
        }];
        let decision = RouteDecision {
            provider,
            model: "non-streaming-model".to_string(),
            upstream_channel: Channel::Chat,
        };
        assert!(!route_supports_incremental_cross_protocol_stream(
            &Channel::Responses,
            &decision
        ));
    }

    fn prefix_state(
        input_tokens: u64,
        cache_read_tokens: u64,
        shortfall_tokens: u64,
    ) -> PrefixWarmState {
        let record = UsageRecord {
            input_tokens,
            cache_read_tokens,
            ..UsageRecord::default()
        };
        PrefixWarmState {
            finished_at: Instant::now(),
            input_tokens,
            cache_read_tokens,
            shortfall_tokens,
            seen_bucket_tokens: provider_cache_bucket_max(input_tokens),
            avoidable_shortfall_tokens: shortfall_tokens,
            avoidable_shortfall_streak: u32::from(shortfall_tokens > 0),
            shortfall_tokens_128: provider_cache_shortfall_128(&record),
            seen_bucket_tokens_128: provider_cache_bucket_max_128(input_tokens),
            avoidable_shortfall_tokens_128: shortfall_tokens,
            small_gap_recovery_streak: u32::from(shortfall_tokens > 0 && shortfall_tokens <= 2048),
            recent_clean_tiny_gap_streak: 0,
            cache_instability_score: 0,
            settle_after_cold_read: false,
            tail_tool_output_chars: 0,
            tail_largest_tool_output_chars: 0,
            tail_tool_output_noise_hint: None,
            responses_static_projection_digest: None,
        }
    }

    async fn seed_native_maturity_scope(
        state: &AppState,
        prefix_control_key: &str,
        parent_scope_digest: &str,
        prefix: PrefixWarmState,
    ) {
        state.prefix_maturity_scopes.lock().await.insert(
            prefix_control_key,
            parent_scope_digest,
            prefix,
        );
    }

