    #[test]
    fn isolated_options_sibling_settle_hint_requires_a_fresh_stable_sibling() {
        let mut exact = prefix_state(200_000, 199_800, 0);
        exact.finished_at = Instant::now()
            .checked_sub(StdDuration::from_millis(501))
            .expect("the test clock supports a bounded stale state");
        let mut sibling = prefix_state(200_000, 199_800, 0);

        assert!(isolated_options_sibling_should_supply_settle_hint(
            Some(&exact),
            Some(&sibling),
        ));

        exact.finished_at = Instant::now();
        assert!(
            !isolated_options_sibling_should_supply_settle_hint(Some(&exact), Some(&sibling)),
            "a fresh exact state must remain authoritative over a sibling"
        );

        exact.finished_at = Instant::now()
            .checked_sub(StdDuration::from_millis(501))
            .expect("the test clock supports a bounded stale state");
        sibling.settle_after_cold_read = true;
        assert!(
            !isolated_options_sibling_should_supply_settle_hint(Some(&exact), Some(&sibling)),
            "a cold-read sibling must never trigger the proactive wait"
        );

        sibling.settle_after_cold_read = false;
        sibling.cache_instability_score = 3;
        assert!(
            !isolated_options_sibling_should_supply_settle_hint(Some(&exact), Some(&sibling)),
            "an unstable sibling must fail open"
        );
    }

    #[tokio::test]
    async fn snapshot_lock_busy_skips_affinity_without_delaying_the_inbound_plan() {
        let shadow_affinity =
            tokio::sync::Mutex::new(cache_affinity::ShadowAffinityStore::default());
        let identity = affinity_identity::AffinityIdentity {
            realm_id: "snapshot-lock-realm".to_string(),
            cohort_id: "snapshot-lock-cohort".to_string(),
            stable_prefix_digest: "snapshot-lock-prefix".to_string(),
            trusted_conversation_id: Some("snapshot-lock-conversation".to_string()),
            trusted_identity_source: Some("thread-id".to_string()),
        };
        let held = shadow_affinity.lock().await;

        let started = Instant::now();
        let (busy, lock_busy) = try_compute_shadow_affinity_without_wait(
            &shadow_affinity,
            &identity,
            None,
            std::time::Duration::ZERO,
            Utc::now(),
            0,
            0,
        );

        assert!(lock_busy);
        assert!(started.elapsed() < TokioDuration::from_millis(5));
        assert_eq!(busy.mode, "shadow");
        assert_eq!(busy.decision, "snapshot_lock_busy");
        assert_eq!(
            busy.skip_reason.as_deref(),
            Some("runtime_snapshot_lock_busy")
        );
        assert_eq!(busy.lane, cache_affinity::ShadowCacheLane::Transparent);
        drop(held);

        let (available, lock_busy) = try_compute_shadow_affinity_without_wait(
            &shadow_affinity,
            &identity,
            None,
            std::time::Duration::ZERO,
            Utc::now(),
            0,
            0,
        );
        assert!(!lock_busy);
        assert!(available.assignment_key.is_some());
        assert_eq!(available.skip_reason, None);
    }

    #[tokio::test]
    async fn responses_prefix_snapshot_busy_fails_open_without_spending_wait_budget() {
        let dir = std::env::temp_dir().join(format!(
            "atoapi-prefix-snapshot-lock-{}",
            Uuid::new_v4().simple()
        ));
        let state = AppState::for_test(
            AppConfig::default(),
            dir.join("config.toml"),
            CacheStore::load(cache_path(&dir)).unwrap(),
        )
        .unwrap();
        let mut held = state.prefix_states.clone().lock_owned().await;
        held.insert(
            "snapshot-prefix".to_string(),
            prefix_state(64_512, 63_872, 0),
        );
        let release = tokio::spawn(async move {
            sleep(TokioDuration::from_millis(20)).await;
            drop(held);
        });

        let started = Instant::now();
        let wait = tokio::time::timeout(
            TokioDuration::from_millis(100),
            wait_for_provider_prefix_settle(
                &state,
                &Channel::Responses,
                Some("snapshot-prefix"),
                None,
                &TailInputDiagnostics::default(),
                false,
                Some(TokioDuration::ZERO),
            ),
        )
        .await
        .expect("a busy snapshot must fail open promptly");

        assert!(started.elapsed() < TokioDuration::from_millis(5));
        assert_eq!(wait.source, None);
        assert_eq!(
            wait.skip_reason.as_deref(),
            Some("prefix_state_snapshot_busy")
        );
        assert!(wait.wait_duration.is_zero());
        assert_eq!(wait.wait_ms, 0);
        assert!(!wait.recovery_applicable);
        release.await.unwrap();
        fs::remove_dir_all(dir).ok();
    }

