    #[test]
    fn attested_codex_turn_metadata_is_not_forwarded_on_native_responses_wire() {
        let mut headers = HeaderMap::new();
        headers.insert(
            X_CODEX_TURN_METADATA_HEADER,
            HeaderValue::from_static(r#"{"thread_id":"thread-a","session_id":"session-a"}"#),
        );

        let mut object_carrier = json!({
            "client_metadata": {
                "x-codex-turn-metadata": {
                    "thread_id": "thread-a",
                    "session_id": "session-a",
                    "turn_nonce": "first"
                },
                "upstream_tag": "preserve"
            },
            "input": []
        });
        let trusted = trusted_codex_request_metadata_for_request(&headers, &object_carrier, true)
            .expect(
                "matching Codex identity must be attested before its private carrier is removed",
            );
        strip_attested_codex_turn_metadata_from_native_wire(
            &mut object_carrier,
            true,
            Some(&trusted),
        );
        assert_eq!(
            object_carrier.pointer("/client_metadata/upstream_tag"),
            Some(&json!("preserve"))
        );
        assert!(object_carrier
            .pointer("/client_metadata/x-codex-turn-metadata")
            .is_none());

        let mut next_turn = json!({
            "client_metadata": {
                "x-codex-turn-metadata": {
                    "thread_id": "thread-a",
                    "session_id": "session-a",
                    "turn_nonce": "second"
                },
                "upstream_tag": "preserve"
            },
            "input": [{"type":"message","role":"user","content":"next"}]
        });
        strip_attested_codex_turn_metadata_from_native_wire(&mut next_turn, true, Some(&trusted));
        let first_wire = PreparedWireRequest::from_value(&Channel::Responses, &object_carrier);
        let next_wire = PreparedWireRequest::from_value(&Channel::Responses, &next_turn);
        assert_eq!(
            first_wire.responses_static_projection_digest(),
            next_wire.responses_static_projection_digest(),
            "a private per-turn carrier must not split the final static Responses prefix"
        );

        let mut control_only_string = json!({
            "client_metadata": r#"{"x-codex-turn-metadata":{"thread_id":"thread-a","session_id":"session-a"}}"#,
            "input": []
        });
        strip_attested_codex_turn_metadata_from_native_wire(
            &mut control_only_string,
            true,
            Some(&trusted),
        );
        assert!(control_only_string.get("client_metadata").is_none());

        let mixed_raw = r#"{ "x-codex-turn-metadata":{"thread_id":"thread-a","session_id":"session-a","turn_nonce":"first"},  "upstream_tag" : "preserve" }"#;
        let mut mixed_string = json!({"client_metadata": mixed_raw, "input": []});
        strip_attested_codex_turn_metadata_from_native_wire(
            &mut mixed_string,
            true,
            Some(&trusted),
        );
        assert_eq!(
            mixed_string.get("client_metadata").and_then(Value::as_str),
            Some(r#"{  "upstream_tag" : "preserve" }"#),
            "the leading private carrier must be removed without reserializing the caller-owned sibling"
        );
        let mut mixed_next_turn = json!({
            "client_metadata": r#"{ "x-codex-turn-metadata":{"thread_id":"thread-a","session_id":"session-a","turn_nonce":"second"},  "upstream_tag" : "preserve" }"#,
            "input": [{"type":"message","role":"user","content":"next"}]
        });
        strip_attested_codex_turn_metadata_from_native_wire(
            &mut mixed_next_turn,
            true,
            Some(&trusted),
        );
        let first_mixed_wire = PreparedWireRequest::from_value(&Channel::Responses, &mixed_string);
        let next_mixed_wire =
            PreparedWireRequest::from_value(&Channel::Responses, &mixed_next_turn);
        assert_eq!(
            first_mixed_wire.responses_static_projection_digest(),
            next_mixed_wire.responses_static_projection_digest(),
            "a changing leading carrier in an otherwise opaque JSON string must not split the static wire"
        );

        let carrier_after_sibling = r#"{"upstream_tag":"preserve","x-codex-turn-metadata":{"thread_id":"thread-a","session_id":"session-a","turn_nonce":"later"}}"#;
        let mut reordered_mixed_string =
            json!({"client_metadata": carrier_after_sibling, "input": []});
        strip_attested_codex_turn_metadata_from_native_wire(
            &mut reordered_mixed_string,
            true,
            Some(&trusted),
        );
        assert_eq!(
            reordered_mixed_string
                .get("client_metadata")
                .and_then(Value::as_str),
            Some(r#"{"upstream_tag":"preserve"}"#),
            "an attested private carrier after a caller-owned sibling must be removed without reserializing that sibling"
        );
        let mut reordered_next_turn = json!({
            "client_metadata": r#"{"upstream_tag":"preserve","x-codex-turn-metadata":{"thread_id":"thread-a","session_id":"session-a","turn_nonce":"later-next"}}"#,
            "input": [{"type":"message","role":"user","content":"next"}]
        });
        strip_attested_codex_turn_metadata_from_native_wire(
            &mut reordered_next_turn,
            true,
            Some(&trusted),
        );
        let first_reordered_wire =
            PreparedWireRequest::from_value(&Channel::Responses, &reordered_mixed_string);
        let next_reordered_wire =
            PreparedWireRequest::from_value(&Channel::Responses, &reordered_next_turn);
        assert_eq!(
            first_reordered_wire.responses_static_projection_digest(),
            next_reordered_wire.responses_static_projection_digest(),
            "a changing non-leading private carrier must not split the final static Responses prefix"
        );

        let mut mismatched = json!({
            "client_metadata": {
                "x-codex-turn-metadata": {"thread_id":"thread-b","session_id":"session-a"}
            },
            "input": []
        });
        strip_attested_codex_turn_metadata_from_native_wire(&mut mismatched, true, Some(&trusted));
        assert!(mismatched
            .pointer("/client_metadata/x-codex-turn-metadata")
            .is_some());

        let mut non_native = json!({
            "client_metadata": {
                "x-codex-turn-metadata": {"thread_id":"thread-a","session_id":"session-a"}
            },
            "input": []
        });
        strip_attested_codex_turn_metadata_from_native_wire(&mut non_native, false, Some(&trusted));
        assert!(non_native
            .pointer("/client_metadata/x-codex-turn-metadata")
            .is_some());
    }

    #[test]
    fn json_string_metadata_splicer_removes_only_one_unambiguous_top_level_carrier() {
        let target = X_CODEX_TURN_METADATA_HEADER;
        assert_eq!(
            strip_json_string_metadata_member(
                r#"{ "x-codex-turn-metadata":{"turn_nonce":"one"},  "upstream_tag" : "preserve" }"#,
                target,
            ),
            Some(r#"{  "upstream_tag" : "preserve" }"#.to_string())
        );
        assert_eq!(
            strip_json_string_metadata_member(
                r#"{"first":"keep","x-codex-turn-metadata":{"turn_nonce":"one"},"last":"keep"}"#,
                target,
            ),
            Some(r#"{"first":"keep","last":"keep"}"#.to_string())
        );
        assert_eq!(
            strip_json_string_metadata_member(
                r#"{"first":"keep","x-codex-turn-metadata":{"turn_nonce":"one"}}"#,
                target,
            ),
            Some(r#"{"first":"keep"}"#.to_string())
        );
        assert!(
            strip_json_string_metadata_member(
                r#"{"x-codex-turn-metadata":{"turn_nonce":"one"},"keep":true,"x-codex-turn-metadata":{"turn_nonce":"two"}}"#,
                target,
            )
            .is_none(),
            "duplicate control keys are ambiguous and must be forwarded unchanged"
        );
        assert!(
            strip_json_string_metadata_member(
                r#"{"keep":{"x-codex-turn-metadata":{"turn_nonce":"one"}},"other":true}"#,
                target,
            )
            .is_none(),
            "only a top-level private carrier is eligible"
        );
    }

    #[test]
    fn adapter_header_identity_must_agree_with_every_forwarded_body_identity() {
        let mut headers = HeaderMap::new();
        headers.insert(
            X_CODEX_TURN_METADATA_HEADER,
            HeaderValue::from_static(
                r#"{"session_id":"session-a","thread_id":"thread-a","conversation_id":"conversation-a","request_kind":"turn"}"#,
            ),
        );
        let matching = json!({
            "thread_id": "thread-a",
            "session_id": "session-a",
            "conversation_id": "conversation-a",
            "client_metadata": {
                "x-codex-turn-metadata": {
                    "session_id": "session-a",
                    "thread_id": "thread-a",
                    "conversation_id": "conversation-a",
                    "request_kind": "turn"
                }
            }
        });
        let trusted = trusted_codex_request_metadata_for_request(&headers, &matching, true)
            .expect("matching header and body identities should remain attested");
        assert_eq!(trusted.source, TrustedCodexMetadataSource::AdapterHeader);

        let mut conflicting_top_level = matching.clone();
        conflicting_top_level["thread_id"] = json!("thread-b");
        assert!(
            trusted_codex_request_metadata_for_request(&headers, &conflicting_top_level, true)
                .is_none()
        );

        let mut padded_top_level = matching.clone();
        padded_top_level["thread_id"] = json!("thread-a\t");
        assert!(
            trusted_codex_request_metadata_for_request(&headers, &padded_top_level, true).is_none()
        );

        let mut unknown_embedded_kind = matching.clone();
        unknown_embedded_kind["client_metadata"][X_CODEX_TURN_METADATA_HEADER]["request_kind"] =
            json!("review");
        assert!(
            trusted_codex_request_metadata_for_request(&headers, &unknown_embedded_kind, true)
                .is_none()
        );

        let mut conflicting_top_level_kind = matching.clone();
        conflicting_top_level_kind["request_kind"] = json!("compaction");
        assert!(trusted_codex_request_metadata_for_request(
            &headers,
            &conflicting_top_level_kind,
            true,
        )
        .is_none());

        let mut conflicting_embedded = matching;
        conflicting_embedded["client_metadata"][X_CODEX_TURN_METADATA_HEADER]["session_id"] =
            json!("session-b");
        assert!(
            trusted_codex_request_metadata_for_request(&headers, &conflicting_embedded, true)
                .is_none()
        );

        let mut invalid_header = HeaderMap::new();
        invalid_header.insert(
            X_CODEX_TURN_METADATA_HEADER,
            HeaderValue::from_static("not-json"),
        );
        assert!(
            trusted_codex_request_metadata_for_request(
                &invalid_header,
                &json!({
                    "client_metadata": {
                        "x-codex-turn-metadata": {
                            "session_id": "session-a",
                            "thread_id": "thread-a"
                        }
                    }
                }),
                true,
            )
            .is_none(),
            "an invalid supplied adapter header must not fall back to a different identity source"
        );
    }

    #[test]
    fn codex_turn_metadata_rejects_any_supplied_invalid_identity_dimension() {
        for invalid_thread in [
            Value::String(String::new()),
            Value::String("x".repeat(513)),
            Value::String("thread\0other".to_string()),
            Value::String("thread-with-tab\t".to_string()),
            Value::Number(7.into()),
            Value::Null,
        ] {
            let metadata = json!({
                "thread_id": invalid_thread,
                "session_id": "shared-session",
                "request_kind": "turn"
            });
            assert!(
                trusted_codex_request_metadata_from_value(
                    &metadata,
                    TrustedCodexMetadataSource::AdapterHeader,
                )
                .is_none(),
                "an invalid supplied thread_id must not be dropped from an otherwise valid scope"
            );
        }

        for invalid_kind in [json!("review"), json!(7), Value::Null] {
            assert!(trusted_codex_request_metadata_from_value(
                &json!({"session_id":"shared-session","request_kind":invalid_kind}),
                TrustedCodexMetadataSource::AdapterHeader,
            )
            .is_none());
        }
    }

    #[test]
    fn response_session_update_does_not_replace_longer_prefix_with_older_shorter_input() {
        let shorter = json!([
            { "type": "message", "role": "user", "content": "one" }
        ]);
        let model_output_only_longer = json!([
            { "type": "message", "role": "user", "content": "one" },
            { "type": "message", "role": "assistant", "content": "two" }
        ]);
        let longer = json!([
            { "type": "message", "role": "user", "content": "one" },
            { "type": "message", "role": "assistant", "content": "two" },
            { "type": "message", "role": "user", "content": "three" }
        ]);
        let different = json!([
            { "type": "message", "role": "user", "content": "changed" }
        ]);

        assert!(!should_replace_response_session(&longer, &shorter));
        assert!(should_replace_response_session(
            &shorter,
            &model_output_only_longer
        ));
        assert!(should_replace_response_session(&shorter, &longer));
        assert!(should_replace_response_session(&longer, &different));
    }

    #[tokio::test]
    async fn external_previous_response_id_never_mutates_local_lineage() {
        let dir = std::env::temp_dir().join(format!(
            "atoapi-external-continuation-lineage-{}",
            Uuid::new_v4().simple()
        ));
        let state = AppState::for_test(
            AppConfig::default(),
            dir.join("config.toml"),
            CacheStore::load(dir.join("cache.bin")).unwrap(),
        )
        .unwrap();
        state
            .continuation_lineage
            .seed_for_test(
                "thread",
                ResponseSessionState {
                    generation: 1,
                    parent_generation: None,
                    response_id: "resp-local".to_string(),
                    static_projection_digest: None,
                    output_items_complete: false,
                    input: json!([{"type":"message","role":"user","content":"local"}]),
                    output_items: Vec::new(),
                    finished_at: Instant::now(),
                },
            )
            .await;
        let lease = state.continuation_lineage.begin("thread").await;
        let external_input = json!([{"type":"message","role":"user","content":"external"}]);

        assert_eq!(
            update_response_session_with_id(
                &state,
                Some(&lease),
                &LineageParent::ExternalContinuation,
                Some(&external_input),
                None,
                None,
                false,
                Some("resp-external".to_string()),
                Vec::new(),
            )
            .await,
            Some(LineageCommitOutcome::ExternalContinuation)
        );
        let head = state.continuation_lineage.head("thread").await.unwrap();
        assert_eq!(head.response_id, "resp-local");
        assert_eq!(head.generation, 1);
        fs::remove_dir_all(dir).ok();
    }

