    #[tokio::test]
    async fn stream_upstream_forwards_complete_stream_once_when_consumed_normally() {
        let config_dir = std::env::temp_dir().join(format!(
            "atoapi-stream-normal-{}",
            Utc::now().timestamp_nanos_opt().unwrap_or_default()
        ));
        let writer_started = Arc::new(AtomicBool::new(false));
        let writer_release = Arc::new(AtomicBool::new(false));
        let writer_started_for_job = writer_started.clone();
        let writer_release_for_job = writer_release.clone();
        let cache =
            CacheStore::load_with_persistence_job(cache_path(&config_dir), move |operation| {
                assert_eq!(operation, crate::persistence::WriteOperation::Snapshot);
                writer_started_for_job.store(true, Ordering::Release);
                while !writer_release_for_job.load(Ordering::Acquire) {
                    std::thread::sleep(std::time::Duration::from_millis(1));
                }
                Ok(())
            })
            .unwrap();
        let mut config = AppConfig::default();
        config.cache.enabled = true;
        config.cache.exact_enabled = true;
        config.cache.persist_encrypted = true;
        let state = Arc::new(
            AppState::for_test(config.clone(), config_dir.join("config.toml"), cache).unwrap(),
        );

        let upstream_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let upstream_addr = upstream_listener.local_addr().unwrap();
        let upstream_hits = Arc::new(AtomicUsize::new(0));
        let upstream_hits_for_server = upstream_hits.clone();
        let upstream_app = Router::new().route(
            "/stream",
            axum::routing::post(move || {
                let upstream_hits = upstream_hits_for_server.clone();
                async move {
                    upstream_hits.fetch_add(1, Ordering::SeqCst);
                    let stream = async_stream::stream! {
                        yield Ok::<Bytes, Infallible>(Bytes::from_static(
                            b"data: {\"type\":\"response.created\",\"response\":{\"id\":\"resp_normal\"}}\n\n",
                        ));
                        tokio::time::sleep(std::time::Duration::from_millis(25)).await;
                        yield Ok::<Bytes, Infallible>(Bytes::from_static(
                            b"data: {\"type\":\"response.output_text.delta\",\"delta\":\"hello\"}\n\n",
                        ));
                        yield Ok::<Bytes, Infallible>(Bytes::from_static(
                            b"data: {\"type\":\"response.completed\",\"response\":{\"id\":\"resp_normal\",\"usage\":{\"input_tokens\":2,\"output_tokens\":1,\"input_tokens_details\":{\"cached_tokens\":1}}}}\n\n",
                        ));
                        yield Ok::<Bytes, Infallible>(Bytes::from_static(b"data: [DONE]\n\n"));
                    };
                    Response::builder()
                        .status(StatusCode::OK)
                        .header(header::CONTENT_TYPE, "text/event-stream")
                        .body(Body::from_stream(stream))
                        .unwrap()
                }
            }),
        );
        tokio::spawn(async move {
            axum::serve(upstream_listener, upstream_app).await.unwrap();
        });

        let upstream = state
            .upstream_client(false)
            .post(format!("http://{upstream_addr}/stream"))
            .send()
            .await
            .unwrap();
        let response_session_lease = state
            .continuation_lineage
            .begin("normal-response-session")
            .await;
        let response_sessions_guard = state.continuation_lineage.hold_mutations_for_test().await;
        let response = stream_upstream(
            state.clone(),
            upstream,
            "text/event-stream".to_string(),
            200,
            Instant::now(),
            "normal-request".to_string(),
            Channel::Responses,
            RouteDecision {
                provider: test_responses_provider(format!("http://{upstream_addr}/v1")),
                model: "gpt-5.5".to_string(),
                upstream_channel: Channel::Responses,
            },
            true,
            vec!["normal-stream-cache-key".to_string()],
            "cache-key".to_string(),
            None,
            None,
            None,
            None,
            None,
            None,
            config.clone(),
            None,
            None,
            Some("normal-response-session".to_string()),
            Some(json!([{
                "type": "message",
                "role": "user",
                "content": "hello"
            }])),
            Some(response_session_lease),
            LineageParent::FullReplay,
            false,
            false,
            false,
            BodyDiagnostics::default(),
            TailInputDiagnostics::default(),
            SessionAnchorDiagnostics::default(),
            ResponseSessionReuseDiagnostics::default(),
            None,
            None,
            None,
            None,
            PrefixGuardWaitDiagnostics::default(),
            0,
            UpstreamRequestDiagnostics::default(),
            None,
            0,
            None,
            None,
            false,
            None,
            None,
            None,
        )
        .await;

        let body = tokio::time::timeout(
            std::time::Duration::from_secs(1),
            axum::body::to_bytes(response.into_body(), usize::MAX),
        )
        .await
        .expect("client EOF must not wait for response-session settlement")
        .unwrap();
        let text = String::from_utf8(body.to_vec()).unwrap();
        assert!(text.contains("hello"));
        assert_eq!(text.matches("\"type\":\"response.completed\"").count(), 1);
        assert_eq!(upstream_hits.load(Ordering::SeqCst), 1);

        assert_eq!(
            state.metrics.snapshot().await.recent_upstream_calls.len(),
            0,
            "settlement should still be blocked while the client has already received EOF"
        );
        drop(response_sessions_guard);
        let metrics = tokio::time::timeout(std::time::Duration::from_secs(1), async {
            loop {
                let metrics = state.metrics.snapshot().await;
                if metrics.recent_upstream_calls.len() == 1 {
                    break metrics;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("settlement should finish after the blocked state lock is released");
        assert_eq!(metrics.recent_upstream_calls.len(), 1);
        assert_eq!(metrics.recent_requests.len(), 1);
        let log = &metrics.recent_requests[0];
        assert!(
            log.first_byte_ms
                .is_some_and(|first_byte_ms| first_byte_ms < log.ttft_ms),
            "the first raw SSE frame must be recorded before the later model-text event"
        );
        assert_eq!(log.sse_end_reason.as_deref(), Some("upstream_eof"));
        assert_eq!(log.downstream_disconnected, Some(false));
        assert_eq!(log.sse_completed_event_seen, Some(true));
        assert_eq!(log.sse_done_marker_seen, Some(true));

        tokio::time::timeout(std::time::Duration::from_secs(1), async {
            while !writer_started.load(Ordering::Acquire) {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("cache persistence must start after the client has already received EOF");
        let next_lookup = tokio::time::timeout(
            std::time::Duration::from_millis(50),
            state
                .cache
                .lookup_exact("normal-stream-cache-key", &config.cache),
        )
        .await
        .expect("a slow disk writer must not block the next cache lookup");
        assert!(next_lookup.is_some());
        writer_release.store(true, Ordering::Release);
        state.cache.flush().await.unwrap();

        fs::remove_dir_all(config_dir).ok();
    }

    #[tokio::test]
    async fn stream_upstream_emits_one_native_failure_after_a_truncated_responses_stream() {
        let config_dir = std::env::temp_dir().join(format!(
            "atoapi-stream-truncated-responses-{}",
            Uuid::new_v4().simple()
        ));
        let state = Arc::new(
            AppState::for_test(
                AppConfig::default(),
                config_dir.join("config.toml"),
                CacheStore::load(cache_path(&config_dir)).unwrap(),
            )
            .unwrap(),
        );

        let upstream_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let upstream_addr = upstream_listener.local_addr().unwrap();
        let upstream_hits = Arc::new(AtomicUsize::new(0));
        let upstream_hits_for_server = upstream_hits.clone();
        let upstream_app = Router::new().route(
            "/stream",
            axum::routing::post(move || {
                let upstream_hits = upstream_hits_for_server.clone();
                async move {
                    upstream_hits.fetch_add(1, Ordering::SeqCst);
                    let stream = async_stream::stream! {
                        for index in 0..94 {
                            yield Ok::<Bytes, Infallible>(Bytes::from(format!(
                                "event: response.output_text.delta\ndata: {{\"type\":\"response.output_text.delta\",\"delta\":\"chunk-{index}\"}}\n\n"
                            )));
                        }
                    };
                    Response::builder()
                        .status(StatusCode::OK)
                        .header(header::CONTENT_TYPE, "text/event-stream")
                        .header("x-request-id", "upstream-trace-94")
                        .body(Body::from_stream(stream))
                        .unwrap()
                }
            }),
        );
        tokio::spawn(async move {
            axum::serve(upstream_listener, upstream_app).await.unwrap();
        });

        let upstream = state
            .upstream_client(false)
            .post(format!("http://{upstream_addr}/stream"))
            .send()
            .await
            .unwrap();
        let mut upstream_diagnostics = UpstreamRequestDiagnostics::default();
        upstream_diagnostics.upstream_trace_source = Some("x-request-id".to_string());
        upstream_diagnostics.upstream_trace_id = Some("upstream-trace-94".to_string());
        let response = stream_upstream(
            state.clone(),
            upstream,
            "text/event-stream".to_string(),
            200,
            Instant::now(),
            "stream-94-trace".to_string(),
            Channel::Responses,
            RouteDecision {
                provider: test_responses_provider(format!("http://{upstream_addr}/v1")),
                model: "gpt-5.6-terra".to_string(),
                upstream_channel: Channel::Responses,
            },
            false,
            Vec::new(),
            "cache-key".to_string(),
            None,
            None,
            None,
            None,
            None,
            None,
            AppConfig::default(),
            None,
            None,
            None,
            None,
            None,
            LineageParent::FullReplay,
            false,
            false,
            false,
            BodyDiagnostics::default(),
            TailInputDiagnostics::default(),
            SessionAnchorDiagnostics::default(),
            ResponseSessionReuseDiagnostics::default(),
            None,
            None,
            None,
            None,
            PrefixGuardWaitDiagnostics::default(),
            0,
            upstream_diagnostics,
            None,
            0,
            None,
            None,
            false,
            None,
            None,
            None,
        )
        .await;

        let body = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let text = String::from_utf8(body.to_vec()).unwrap();
        assert_eq!(
            text.matches("event: response.output_text.delta").count(),
            94
        );
        assert_eq!(text.matches("event: response.failed").count(), 1);
        assert!(!text.contains("event: response.completed"));
        assert!(text.contains("\"code\":\"upstream_incomplete_eof\""));
        assert!(text.contains("atoapi_trace_id=stream-94-trace"));
        assert!(text.contains("upstream_trace=x-request-id:upstream-trace-94"));
        assert_eq!(upstream_hits.load(Ordering::SeqCst), 1);

        let metrics = tokio::time::timeout(std::time::Duration::from_secs(2), async {
            loop {
                let metrics = state.metrics.snapshot().await;
                if metrics.recent_failed_requests.len() == 1 {
                    break metrics;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("truncated stream settlement must complete");
        assert_eq!(metrics.upstream_requests, 1);
        assert_eq!(
            metrics.recent_failed_requests[0].sse_end_reason.as_deref(),
            Some("upstream_incomplete_eof")
        );
        assert_eq!(
            metrics.recent_failed_requests[0]
                .upstream_trace_id
                .as_deref(),
            Some("upstream-trace-94")
        );
        assert!(metrics
            .recent_errors
            .iter()
            .any(|error| error.scope == "upstream_sse_error"));

        fs::remove_dir_all(config_dir).ok();
    }

