    #[tokio::test]
    async fn final_scope_predecessor_proof_is_exact_and_fail_closed_for_field_drift() {
        let config = AppConfig::default();
        let dir = std::env::temp_dir().join(format!(
            "atoapi-final-scope-predecessor-proof-{}",
            Utc::now().timestamp_nanos_opt().unwrap_or_default()
        ));
        let cache = CacheStore::load(dir.join("cache.bin")).unwrap();
        let state = AppState::for_test(config, dir.join("config.toml"), cache).unwrap();
        let previous_input = json!([
            {
                "type": "message",
                "role": "user",
                "content": "anchor",
                "x_unknown": {"phase": null, "error": {"code": "E1"}}
            },
            {
                "type": "function_call_output",
                "call_id": "call_exact",
                "output": {"stdout": "ok", "stderr": "", "exit_code": 0}
            }
        ]);
        state
            .continuation_lineage
            .seed_for_test(
                "proof-anchor",
                ResponseSessionState {
                    generation: 4,
                    parent_generation: Some(3),
                    response_id: "resp-proof".to_string(),
                    static_projection_digest: None,
                    output_items_complete: false,
                    input: previous_input.clone(),
                    output_items: Vec::new(),
                    finished_at: Instant::now(),
                },
            )
            .await;
        let lease = state.continuation_lineage.begin("proof-anchor").await;
        let mut exact_items = previous_input.as_array().unwrap().clone();
        exact_items.push(json!({
            "type": "message",
            "role": "user",
            "content": "continue"
        }));
        let exact_input = Value::Array(exact_items.clone());

        let exact =
            analyze_tail_input_for_session(&Channel::Responses, Some(&lease), Some(&exact_input));
        assert_eq!(exact.predecessor.status, PredecessorProofStatus::Exact);
        assert!(exact.predecessor.is_exact());
        assert_eq!(exact.predecessor.predecessor_input_items, 2);
        assert_eq!(exact.predecessor.current_input_items, 3);

        let mut unknown_changed = exact_items.clone();
        unknown_changed[0]["x_unknown"]["error"]["code"] = json!("E2");
        let unknown_changed = Value::Array(unknown_changed);
        assert_eq!(
            analyze_tail_input_for_session(
                &Channel::Responses,
                Some(&lease),
                Some(&unknown_changed),
            )
            .predecessor
            .status,
            PredecessorProofStatus::PrefixMismatch
        );

        let mut call_id_changed = exact_items;
        call_id_changed[1]["call_id"] = json!("call_other");
        let call_id_changed = Value::Array(call_id_changed);
        assert_eq!(
            analyze_tail_input_for_session(
                &Channel::Responses,
                Some(&lease),
                Some(&call_id_changed),
            )
            .predecessor
            .status,
            PredecessorProofStatus::PrefixMismatch
        );
        assert_eq!(
            analyze_tail_input_for_session(
                &Channel::Responses,
                Some(&lease),
                Some(&previous_input),
            )
            .predecessor
            .status,
            PredecessorProofStatus::NotExtended
        );
        assert_eq!(
            analyze_tail_input_for_session(&Channel::Responses, Some(&lease), None)
                .predecessor
                .status,
            PredecessorProofStatus::MissingCurrentInput
        );

        fs::remove_dir_all(dir).ok();
    }

    #[tokio::test]
    async fn terminal_publication_timeout_keeps_a_control_prefix_without_exposing_a_semantic_head()
    {
        let lineage = crate::continuation_lineage::ContinuationLineageIndex::default();
        let previous_input = json!([
            { "type": "message", "role": "user", "content": "stable prefix" },
            {
                "type": "function_call_output",
                "call_id": "call-stable",
                "output": { "stdout": "ok", "stderr": "", "exit_code": 0 }
            }
        ]);
        lineage
            .seed_for_test(
                "terminal-fence-prefix",
                ResponseSessionState {
                    generation: 7,
                    parent_generation: Some(6),
                    response_id: "resp-stable".to_string(),
                    static_projection_digest: None,
                    output_items_complete: false,
                    input: previous_input.clone(),
                    output_items: Vec::new(),
                    finished_at: Instant::now(),
                },
            )
            .await;
        let publication = lineage.register_terminal_publication("terminal-fence-prefix");

        let lease = lineage.begin("terminal-fence-prefix").await;
        assert!(
            lease.head().is_none(),
            "a timed-out terminal fence must still withhold semantic response-id recovery"
        );
        assert_eq!(
            lease
                .control_head()
                .and_then(|head| head.semantic_response_id()),
            Some("resp-stable")
        );

        let mut current_items = previous_input.as_array().unwrap().clone();
        current_items.push(json!({
            "type": "message",
            "role": "user",
            "content": "next turn"
        }));
        let analysis = analyze_tail_input_for_session(
            &Channel::Responses,
            Some(&lease),
            Some(&Value::Array(current_items)),
        );
        assert_eq!(analysis.predecessor.status, PredecessorProofStatus::Exact);
        assert!(analysis.predecessor.is_exact());
        assert_eq!(analysis.predecessor.predecessor_input_items, 2);
        assert_eq!(analysis.predecessor.current_input_items, 3);
        assert!(analysis.diagnostics.delta_from_session);

        drop(publication);
    }

