    async fn isolated_response_continuation_probe_is_one_shot_same_ua_and_sanitized() {
        let hits = Arc::new(AtomicUsize::new(0));
        let captured_bodies = Arc::new(tokio::sync::Mutex::new(Vec::<Value>::new()));
        let hits_for_route = hits.clone();
        let bodies_for_route = captured_bodies.clone();
        let upstream_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let upstream_addr = upstream_listener.local_addr().unwrap();
        let upstream_app = Router::new().route(
            "/v1/responses",
            post(move |headers: HeaderMap, Json(body): Json<Value>| {
                let hits = hits_for_route.clone();
                let captured_bodies = bodies_for_route.clone();
                async move {
                    assert_eq!(
                        headers
                            .get(header::USER_AGENT)
                            .and_then(|value| value.to_str().ok()),
                        Some("Atoapi/continuation-test")
                    );
                    assert_eq!(
                        headers
                            .get(X_ATOAPI_REQUEST_KIND_HEADER)
                            .and_then(|value| value.to_str().ok()),
                        Some(isolated_response_continuation::REQUEST_KIND)
                    );
                    let index = hits.fetch_add(1, Ordering::SeqCst);
                    captured_bodies.lock().await.push(body.clone());
                    let response_id = if index == 0 {
                        assert!(body.get("previous_response_id").is_none());
                        "resp_seed_private"
                    } else {
                        assert_eq!(
                            body.get("previous_response_id").and_then(Value::as_str),
                            Some("resp_seed_private")
                        );
                        "resp_followup_private"
                    };
                    let sse = format!(
                        concat!(
                            "event: response.output_text.delta\n",
                            "data: {{\"type\":\"response.output_text.delta\",\"delta\":\"raw-output-sentinel\"}}\n\n",
                            "event: response.completed\n",
                            "data: {{\"type\":\"response.completed\",\"response\":{{\"id\":\"{}\",\"status\":\"completed\",\"usage\":{{\"input_tokens\":3,\"output_tokens\":1,\"total_tokens\":4}}}}}}\n\n",
                            "data: [DONE]\n\n"
                        ),
                        response_id
                    );
                    (
                        StatusCode::OK,
                        [(header::CONTENT_TYPE, "text/event-stream")],
                        sse,
                    )
                }
            }),
        );
        tokio::spawn(async move {
            axum::serve(upstream_listener, upstream_app).await.unwrap();
        });

        let mut config = AppConfig::default();
        config.local_key = "admin-local-key".to_string();
        let mut provider = test_responses_provider(format!("http://{upstream_addr}/v1"));
        provider.id = "isolated-continuation-provider".to_string();
        provider.custom_user_agent = Some("Atoapi/continuation-test".to_string());
        let expected_realm = isolated_response_continuation_probe_realm(
            &provider,
            "gpt-5.6-terra",
            &SelectedProviderKey {
                secret: provider.api_key_encrypted.clone().unwrap_or_default(),
                key_id: None,
                encrypted_material_digest: None,
            },
        );
        assert_ne!(
            expected_realm,
            affinity_identity::key_realm_id(&SelectedProviderKey {
                secret: provider.api_key_encrypted.clone().unwrap_or_default(),
                key_id: None,
                encrypted_material_digest: None,
            })
        );
        config.providers = vec![provider];
        let dir = std::env::temp_dir().join(format!(
            "atoapi-isolated-continuation-probe-{}",
            Uuid::new_v4().simple()
        ));
        let cache = CacheStore::load(dir.join("cache.bin")).unwrap();
        let state = AppState::for_test(config, dir.join("config.toml"), cache).unwrap();

        let result = run_isolated_response_continuation_probe(
            &state,
            isolated_response_continuation::ProbeInput {
                provider_id: "isolated-continuation-provider".to_string(),
                model_id: "gpt-5.6-terra".to_string(),
                key_id: None,
                key_realm_hash: Some(expected_realm.clone()),
            },
        )
        .await
        .unwrap();

        assert!(result.ok);
        assert_eq!(hits.load(Ordering::SeqCst), 2);
        assert_eq!(result.upstream_request_count, 2);
        assert!(result.seed.response_id_present);
        assert!(result.continuation.previous_response_id_sent);
        assert!(result.continuation.accepted);
        assert!(result.identity.same_user_agent);
        assert_eq!(result.identity.key_realm_hash, expected_realm);
        let captured = captured_bodies.lock().await;
        assert_eq!(captured.len(), 2);
        assert!(captured[0].get("previous_response_id").is_none());
        assert_eq!(
            captured[1]
                .get("previous_response_id")
                .and_then(Value::as_str),
            Some("resp_seed_private")
        );
        drop(captured);
        let sanitized = serde_json::to_string(&result).unwrap();
        assert!(!sanitized.contains("resp_seed_private"));
        assert!(!sanitized.contains("resp_followup_private"));
        assert!(!sanitized.contains("raw-output-sentinel"));
        assert!(!sanitized.contains("Bearer key"));
        fs::remove_dir_all(dir).ok();
    }

    #[tokio::test]
    async fn cache_capability_probe_handles_http_200_semantic_field_rejection() {
        let hits = Arc::new(AtomicUsize::new(0));
        let hits_for_route = hits.clone();
        let upstream_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let upstream_addr = upstream_listener.local_addr().unwrap();
        let upstream_app = Router::new().route(
            "/v1/responses",
            post(move |headers: HeaderMap, Json(body): Json<Value>| {
                let hits = hits_for_route.clone();
                async move {
                    assert_eq!(
                        headers
                            .get(X_ATOAPI_REQUEST_KIND_HEADER)
                            .and_then(|value| value.to_str().ok()),
                        Some(CACHE_CAPABILITY_PROBE_REQUEST_KIND)
                    );
                    hits.fetch_add(1, Ordering::SeqCst);
                    let has_breakpoint = serde_json::to_string(&body)
                        .unwrap_or_default()
                        .contains("prompt_cache_breakpoint");
                    if has_breakpoint {
                        (
                            StatusCode::OK,
                            Json(json!({
                                "type": "response.failed",
                                "response": {
                                    "status": "failed",
                                    "error": {
                                        "code": "invalid_parameter",
                                        "message": "prompt_cache_breakpoint is not supported on this model"
                                    }
                                }
                            })),
                        )
                    } else {
                        (
                            StatusCode::OK,
                            Json(json!({
                                "id": "resp_cache_capability_probe",
                                "error": null,
                                "output": [{
                                    "type": "message",
                                    "content": [{"type": "output_text", "text": "ACK"}]
                                }]
                            })),
                        )
                    }
                }
            }),
        );
        tokio::spawn(async move {
            axum::serve(upstream_listener, upstream_app).await.unwrap();
        });

        let mut config = AppConfig::default();
        let mut provider = test_responses_provider(format!("http://{upstream_addr}/v1"));
        provider.id = "cache-capability-provider".to_string();
        config.providers = vec![provider];
        let dir = std::env::temp_dir().join(format!(
            "atoapi-cache-capability-probe-{}",
            Uuid::new_v4().simple()
        ));
        let cache = CacheStore::load(dir.join("cache.bin")).unwrap();
        let state = AppState::for_test(config, dir.join("config.toml"), cache).unwrap();

        let result = probe_and_record_provider_cache_capabilities(
            &state,
            "cache-capability-provider",
            "gpt-5.6-luna",
            Some(Channel::Responses),
            None,
        )
        .await
        .unwrap();

        assert_eq!(hits.load(Ordering::SeqCst), 5);
        assert_eq!(result.fields.len(), 4);
        assert_eq!(
            result
                .fields
                .iter()
                .find(|item| { item.field == ProviderCacheCapabilityField::PromptCacheBreakpoint })
                .map(|item| item.status.clone()),
            Some(ProviderCacheCapabilityStatus::Unsupported)
        );
        assert!(result
            .fields
            .iter()
            .filter(|item| item.field != ProviderCacheCapabilityField::PromptCacheBreakpoint)
            .all(|item| item.status == ProviderCacheCapabilityStatus::Verified));
        let saved = state.config.read().await;
        assert!(!saved.cache_capability_verified_for(
            "cache-capability-provider",
            "gpt-5.6-luna",
            &Channel::Responses,
            ProviderCacheCapabilityField::PromptCacheOptions,
        ));
        assert_eq!(
            saved.cache_capability_status(
                "cache-capability-provider",
                "gpt-5.6-luna",
                &Channel::Responses,
                ProviderCacheCapabilityField::PromptCacheBreakpoint,
            ),
            ProviderCacheCapabilityStatus::Unsupported
        );
        drop(saved);

        let single_field = probe_and_record_provider_cache_capabilities(
            &state,
            "cache-capability-provider",
            "gpt-5.6-luna",
            Some(Channel::Responses),
            Some(vec![ProviderCacheCapabilityField::PromptCacheKey]),
        )
        .await
        .unwrap();
        assert_eq!(
            hits.load(Ordering::SeqCst),
            7,
            "a one-field certificate must issue only baseline plus that field"
        );
        assert_eq!(single_field.fields.len(), 1);
        assert_eq!(
            single_field.fields[0].field,
            ProviderCacheCapabilityField::PromptCacheKey
        );
        assert_eq!(
            single_field.fields[0].status,
            ProviderCacheCapabilityStatus::Verified
        );
        fs::remove_dir_all(dir).ok();
    }

    #[tokio::test]
    async fn runtime_json_breakpoint_rejection_disables_only_that_field_without_retry() {
        let hits = Arc::new(AtomicUsize::new(0));
        let captured = Arc::new(tokio::sync::Mutex::new(Vec::<Value>::new()));
        let hits_for_route = hits.clone();
        let captured_for_route = captured.clone();
        let upstream_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let upstream_addr = upstream_listener.local_addr().unwrap();
        let upstream_app = Router::new().route(
            "/v1/responses",
            post(move |Json(body): Json<Value>| {
                let hits = hits_for_route.clone();
                let captured = captured_for_route.clone();
                async move {
                    hits.fetch_add(1, Ordering::SeqCst);
                    let has_breakpoint = serde_json::to_string(&body)
                        .unwrap_or_default()
                        .contains("prompt_cache_breakpoint");
                    captured.lock().await.push(body);
                    let (content_type, response_body) = if has_breakpoint {
                        (
                            "application/json",
                            serde_json::to_vec(&json!({
                                "type": "response.failed",
                                "response": {
                                    "id": "resp_breakpoint_rejected",
                                    "status": "failed",
                                    "error": {
                                        "code": "invalid_parameter",
                                        "message": "prompt_cache_breakpoint is not supported on this model"
                                    }
                                }
                            }))
                            .unwrap(),
                        )
                    } else {
                        (
                            "text/event-stream",
                            concat!(
                                "event: response.output_text.delta\n",
                                "data: {\"type\":\"response.output_text.delta\",\"delta\":\"ok\"}\n\n",
                                "event: response.completed\n",
                                "data: {\"type\":\"response.completed\",\"response\":{\"id\":\"resp_breakpoint_recovered\",\"status\":\"completed\",\"usage\":{\"input_tokens\":10,\"output_tokens\":1,\"input_tokens_details\":{\"cached_tokens\":0}}}}\n\n"
                            )
                            .as_bytes()
                            .to_vec(),
                        )
                    };
                    Response::builder()
                        .status(StatusCode::OK)
                        .header(header::CONTENT_TYPE, content_type)
                        .body(Body::from(response_body))
                        .unwrap()
                }
            }),
        );
        tokio::spawn(async move {
            axum::serve(upstream_listener, upstream_app).await.unwrap();
        });

        let provider_id = "runtime-breakpoint-provider";
        let model_id = "gpt-5.6-terra";
        let mut config =
            test_codex_compact_config(format!("http://{upstream_addr}/v1"), provider_id);
        config.cache = crate::config::CacheConfig::smart_max_hit();
        config.providers[0].models = vec![ModelConfig {
            id: model_id.to_string(),
            request_model_id: None,
            display_name: model_id.to_string(),
            context_window: Some(300_000),
            output_window: None,
            reasoning_effort_override_enabled: false,
            reasoning_effort: None,
            supported_reasoning_efforts: Vec::new(),
            supports_tools: true,
            supports_streaming: true,
            enabled: true,
        }];
        let request_payload = json!({
            "model": model_id,
            "stream": true,
            "store": false,
            "input": [{
                "type": "message",
                "role": "user",
                "content": [
                    { "type": "input_text", "text": "stable prefix" },
                    { "type": "input_text", "text": "dynamic tail" }
                ]
            }]
        });
        let breakpoint_placement =
            cache_capability::predicted_responses_breakpoint_placement_digest(&request_payload)
                .expect("the test request has one legal breakpoint position");
        config.record_cache_capability_probe(
            provider_id,
            model_id,
            Channel::Responses,
            ProviderCacheCapabilityField::PromptCacheBreakpoint,
            ProviderCacheCapabilityStatus::Verified,
            None,
        );
        let effect_scope_id = test_responses_effect_scope_id(
            &config.providers[0],
            model_id,
            Some(true),
            Some(false),
            Some(&breakpoint_placement),
        );
        config.record_cache_capability_effect_for_scope(
            provider_id,
            model_id,
            &Channel::Responses,
            None,
            Some(&effect_scope_id),
            &[ProviderCacheCapabilityField::PromptCacheBreakpoint],
            ProviderCacheEffectStatus::Promoted,
            Some("previously verified".to_string()),
            Some(0),
            Some(512),
            Some(100),
            Some(100),
        );
        let dir = std::env::temp_dir().join(format!(
            "atoapi-runtime-breakpoint-rejection-{}",
            Uuid::new_v4().simple()
        ));
        let state = Arc::new(
            AppState::for_test(
                config,
                dir.join("config.toml"),
                CacheStore::load(cache_path(&dir)).unwrap(),
            )
            .unwrap(),
        );
        let request_body = || Bytes::from(serde_json::to_vec(&request_payload).unwrap());

        let first = handle_generation_for_agent(
            state.clone(),
            test_local_auth_headers(),
            request_body(),
            Channel::Responses,
            Some("codex"),
        )
        .await;
        assert_eq!(first.status(), StatusCode::BAD_GATEWAY);
        let first_body = axum::body::to_bytes(first.into_body(), usize::MAX)
            .await
            .unwrap();
        assert!(String::from_utf8_lossy(&first_body)
            .contains("prompt_cache_breakpoint is not supported on this model"));
        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            loop {
                let status = state.config.read().await.cache_capability_status(
                    provider_id,
                    model_id,
                    &Channel::Responses,
                    ProviderCacheCapabilityField::PromptCacheBreakpoint,
                );
                if status == ProviderCacheCapabilityStatus::Unsupported {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("the explicit runtime rejection must disable only the rejected field");
        assert_eq!(hits.load(Ordering::SeqCst), 1);
        let first_metrics = state.metrics.snapshot().await;
        assert_eq!(first_metrics.upstream_requests, 1);
        assert!(first_metrics.recent_requests.is_empty());
        assert_eq!(first_metrics.recent_failed_requests.len(), 1);

        let second = handle_generation_for_agent(
            state.clone(),
            test_local_auth_headers(),
            request_body(),
            Channel::Responses,
            Some("codex"),
        )
        .await;
        let second_body = axum::body::to_bytes(second.into_body(), usize::MAX)
            .await
            .unwrap();
        assert!(String::from_utf8_lossy(&second_body).contains("response.completed"));
        assert_eq!(hits.load(Ordering::SeqCst), 2);
        let captured = captured.lock().await;
        assert_eq!(captured.len(), 2);
        assert!(serde_json::to_string(&captured[0])
            .unwrap()
            .contains("prompt_cache_breakpoint"));
        assert!(!serde_json::to_string(&captured[1])
            .unwrap()
            .contains("prompt_cache_breakpoint"));

        fs::remove_dir_all(dir).ok();
    }

