    #[tokio::test]
    async fn codex_native_cache_key_is_forwarded_once_on_the_normal_wire() {
        // Codex owns this stable placement key. Atoapi must preserve it on an
        // untouched native Responses request instead of replacing it with a
        // generated experiment or stripping it from the normal one-shot wire.
        let raw_client_key = "codex-native-placement-key";
        let upstream_hits = Arc::new(AtomicUsize::new(0));
        let captured_bodies = Arc::new(tokio::sync::Mutex::new(Vec::<Value>::new()));
        let upstream_hits_for_route = upstream_hits.clone();
        let captured_bodies_for_route = captured_bodies.clone();
        let upstream_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let upstream_addr = upstream_listener.local_addr().unwrap();
        let upstream_app = Router::new().route(
            "/v1/responses",
            post(move |Json(body): Json<Value>| {
                let upstream_hits = upstream_hits_for_route.clone();
                let captured_bodies = captured_bodies_for_route.clone();
                async move {
                    upstream_hits.fetch_add(1, Ordering::SeqCst);
                    captured_bodies.lock().await.push(body);
                    raw_response(
                        200,
                        "text/event-stream",
                        concat!(
                            "data: {\"type\":\"response.output_text.delta\",\"delta\":\"ready\"}\n\n",
                            "data: {\"type\":\"response.completed\",\"response\":{\"id\":\"resp_generated_key\",\"usage\":{\"input_tokens\":1024,\"output_tokens\":1,\"input_tokens_details\":{\"cached_tokens\":896}}}}\n\n",
                            "data: [DONE]\n\n"
                        )
                        .as_bytes()
                        .to_vec(),
                    )
                }
            }),
        );
        tokio::spawn(async move {
            axum::serve(upstream_listener, upstream_app).await.unwrap();
        });

        let mut config = AppConfig::default();
        config.local_key = "local-client-key-test".to_string();
        config.workspace_fingerprint = "client-key-cooldown-workspace".to_string();
        config.cache.enabled = true;
        config.cache.mode = CacheMode::PrefixPrewarm;
        let mut provider = test_responses_provider(format!("http://{upstream_addr}/v1"));
        provider.id = "client-key-cooldown-provider".to_string();
        provider.prompt_cache_retention_enabled = true;
        config.providers = vec![provider];
        configure_test_codex_agent(&mut config, "client-key-cooldown-provider");
        let dir = std::env::temp_dir().join(format!(
            "atoapi-client-cache-key-wire-{}",
            Uuid::new_v4().simple()
        ));
        let state = Arc::new(
            AppState::for_test(
                config,
                dir.join("config.toml"),
                CacheStore::load(dir.join("cache.bin")).unwrap(),
            )
            .unwrap(),
        );
        let mut headers = HeaderMap::new();
        headers.insert(
            header::AUTHORIZATION,
            HeaderValue::from_static("Bearer local-client-key-test"),
        );
        headers.insert(
            X_CODEX_TURN_METADATA_HEADER,
            HeaderValue::from_static(
                r#"{"thread_id":"client-key-thread","session_id":"client-key-session"}"#,
            ),
        );
        let request = Bytes::from(
            serde_json::to_vec(&json!({
                "model": "gpt-5.6-sol",
                "stream": true,
                "prompt_cache_key": raw_client_key,
                "prompt_cache_retention": "24h",
                "client_metadata": r#"{"x-codex-turn-metadata":{"thread_id":"client-key-thread","session_id":"client-key-session","turn_nonce":"one"},"upstream_tag":"preserve"}"#,
                "input": [{
                    "type": "message",
                    "role": "user",
                    "content": [{"type": "input_text", "text": "preserve the native client placement"}]
                }]
            }))
            .unwrap(),
        );

        let first = handle_generation_for_agent(
            state.clone(),
            headers.clone(),
            request.clone(),
            Channel::Responses,
            Some("codex"),
        )
        .await;
        assert_eq!(first.status(), StatusCode::OK);
        let _ = axum::body::to_bytes(first.into_body(), usize::MAX)
            .await
            .unwrap();
        assert!(
            state
                .relay_tasks
                .wait_for_idle(std::time::Duration::from_secs(2))
                .await
        );

        assert_eq!(
            upstream_hits.load(Ordering::SeqCst),
            1,
            "each inbound request must create exactly one upstream POST"
        );
        let captured_first = captured_bodies.lock().await;
        assert_eq!(captured_first.len(), 1);
        assert_eq!(
            captured_first[0]
                .get("prompt_cache_key")
                .and_then(Value::as_str),
            Some(raw_client_key),
            "the normal native Codex wire must preserve its stable cache placement"
        );
        assert_eq!(
            captured_first[0]
                .get("client_metadata")
                .and_then(Value::as_str),
            Some(r#"{"upstream_tag":"preserve"}"#),
            "the mixed JSON-string carrier must be removed without changing the caller-owned sibling"
        );
        drop(captured_first);

        let generated_followup = Bytes::from(
            serde_json::to_vec(&json!({
                "model": "gpt-5.6-sol",
                "stream": true,
                "client_metadata": r#"{"x-codex-turn-metadata":{"thread_id":"client-key-thread","session_id":"client-key-session","turn_nonce":"two"},"upstream_tag":"preserve"}"#,
                "input": [{
                    "type": "message",
                    "role": "user",
                    "content": [{"type": "input_text", "text": "continue with verified native cache controls"}]
                }]
            }))
            .unwrap(),
        );
        let second = handle_generation_for_agent(
            state.clone(),
            headers,
            generated_followup,
            Channel::Responses,
            Some("codex"),
        )
        .await;
        assert_eq!(second.status(), StatusCode::OK);
        let _ = axum::body::to_bytes(second.into_body(), usize::MAX)
            .await
            .unwrap();
        assert!(
            state
                .relay_tasks
                .wait_for_idle(std::time::Duration::from_secs(2))
                .await
        );
        assert_eq!(
            upstream_hits.load(Ordering::SeqCst),
            2,
            "two independent inbounds must produce exactly two upstream POSTs"
        );
        let captured_bodies = captured_bodies.lock().await;
        assert_eq!(captured_bodies.len(), 2);
        assert!(
            captured_bodies[1]
                .get("prompt_cache_key")
                .and_then(Value::as_str)
                .is_some(),
            "a successful client key must unlock a stable generated key for the next independent turn"
        );
        assert_eq!(
            captured_bodies[1]
                .get("prompt_cache_retention")
                .and_then(Value::as_str),
            Some("24h"),
            "a successful client retention control must unlock the matching generated retention"
        );
        assert_eq!(
            captured_bodies[1]
                .get("client_metadata")
                .and_then(Value::as_str),
            Some(r#"{"upstream_tag":"preserve"}"#),
            "successive turns with changing private carriers must keep the same outgoing string metadata"
        );
        drop(captured_bodies);

        let cooldown_keys = state
            .client_prompt_cache_key_rejection_cooldowns
            .lock()
            .await
            .keys()
            .cloned()
            .collect::<Vec<_>>();
        assert!(cooldown_keys.is_empty());
        let metrics_json = serde_json::to_string(&state.metrics.snapshot().await).unwrap();
        assert!(
            !metrics_json.contains(raw_client_key),
            "upstream error echoes must not reach metrics/history UI data"
        );
        let config = state.config.read().await;
        for field in [
            ProviderCacheCapabilityField::PromptCacheKey,
            ProviderCacheCapabilityField::PromptCacheRetention,
        ] {
            assert_eq!(
                config.cache_capability_status_for_key(
                    "client-key-cooldown-provider",
                    "gpt-5.6-sol",
                    &Channel::Responses,
                    None,
                    field,
                ),
                ProviderCacheCapabilityStatus::Verified,
                "a completed native client control must passively verify only its accepted field"
            );
        }
        drop(config);
        fs::remove_dir_all(dir).ok();
    }

